    parentName: "blockquote"
  }, "\uBD80\uC870\uB9AC\uD55C \uAC83\uC740 \uBC14\uB85C, \uC774 \uBE44\uD569\uB9AC\uC640 \uBA85\uD655\uD568\uC5D0 \uB300\uD55C \uBBF8\uCE60 \uAC83 \uAC19\uC740 \uC5F4\uB9DD\uC758 \uB9DE\uB300\uBA74\uC774\uB2E4.")), mdx("p", null, "\uCE74\uBB88\uC5D0\uAC8C \uBD80\uC870\uB9AC\uB294 \uC138\uACC4 \uC790\uCCB4\uC758 \uC131\uC9C8\uC774 \uC544\uB2C8\uB77C \uC778\uAC04\uACFC \uC138\uACC4 \uC0AC\uC774\uC758 \uCDA9\uB3CC\uC774\uB2E4. \uC778\uAC04\uC740 \uC758\uBBF8\uC640 \uC124\uBA85\uC744 \uC6D0\uD558\uB294\uB370 \uC138\uACC4\uB294 \uB2F5\uD558\uC9C0 \uC54A\uB294\uB2E4. \uADF8\uB7EC\uB2C8\uAE4C \uC560\uCD08\uC5D0 \uC774\uB7F0 \uC0AC\uB78C\uC740 \uBA4B\uC9C0\uB2C8\uAE4C \uC774\uB7F0 \uC0AC\uB78C\uC774 \uB418\uC5B4\uC57C \uD558\uACA0\uB2E4. \uCC45 \uB0B4\uC6A9\uC774 \uC0DD\uAC01\uBCF4\uB2E4 \uBE61\uC138\uC9C0\uB9CC \uC774\uAC78 \uC870\uAE08\uC774\uB77C\uB3C4 \uC0B6\uC5D0 \uC811\uBAA9\uD558\uACE0 \uB0B4\uAC00 \uD558\uB294 \uC77C\uC744 \uB2F4\uB2F4\uD558\uACE0 \uC5F4\uC2EC\uD788 \uD560 \uC218 \uC788\uB294 '\uAD50\uD6C8' \uB530\uC704\uB97C \uC5BB\uC744 \uC218\uB294 \uC5C6\uC744\uAE4C? - \uB294 \uC0DD\uAC01 \uC790\uCCB4\uAC00 \uC5B4\uB5A4 \uC0B6\uC5D0\uC11C\uC758 \uBA85\uD655\uD55C \uB2F5\uC744 \uC0C1\uC815\uD558\uACE0 \uC788\uB2E4. \uC774 \uCC45\uC744 \uC798 \uC77D\uC5C8\uC744 \uB54C \uADF8\uB7EC\uD55C \uB2F5\uC740 \uC560\uCD08\uC5D0 \uC5C6\uB2E4\uB294 \uAE68\uB2EC\uC74C\uC73C\uB85C \uBC1C\uC804\uD574\uC57C\uD55C\uB2E4. "), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uBC18\uD56D\uC740 \uC778\uAC04\uACFC \uADF8 \uC790\uC2E0\uC758 \uC5B4\uB460\uC758 \uB04A\uC784\uC5C6\uB294 \uB300\uBA74\uC774\uB2E4.  \uBC18\uD56D\uC740 \uB3D9\uACBD\uC774 \uC544\uB2C8\uB2E4. \uBC18\uD56D\uC5D0\uB294 \uD76C\uB9DD\uC774 \uC5C6\uB2E4.")), mdx("p", null, "\uBC18\uD56D\uC5D0\uB294 \uD76C\uB9DD\uC774 \uC5C6\uB2E4. \uC704\uC548\uC774 \uB420 \uB9CC\uD55C \uC5B4\uB5A4 \uC774\uC57C\uAE30\uB3C4 \uB4E4\uC774\uC9C0 \uC54A\uB294 \uC0C1\uD0DC\uAC00 \uBC18\uD56D\uC774\uB2E4. \uCE74\uBB88\uB098 \uB2C8\uCCB4\uC758 \uD14D\uC2A4\uD2B8\uB97C \uBCF4\uBA74\uC11C \uB0B4\uAC00 \uADF8\uB7F0 \uC0AC\uB78C\uC774 \uB418\uC5B4\uC57C\uC9C0, \uB864\uBAA8\uB378\uC740 \uC788\uACE0 \uB098\uB294 \uADF8 \uACBD\uB85C\uB85C \uB2E8\uC120\uC801\uC73C\uB85C \uBC1C\uC804\uD558\uBA74 \uB41C\uB2E4\uB294 \uADF8 \uC0AC\uC2E4 \uC790\uCCB4\uB85C \uC704\uC548\uC744 \uCC3E\uC744 \uC218 \uC788\uB2E4. \uADF8\uB7EC\uB098 \uCE74\uBB88\uC758 \uBC18\uD56D\uC740 \uADF8 \uBAA8\uB4E0 \uC704\uC548\uC744 \uB3C4\uD53C\uC774\uC790 \uBE44\uC57D\uC73C\uB85C \uBD84\uB958\uD55C\uB2E4. \uC790\uAE30\uAC1C\uBC1C\uC11C\uB294 \uD604\uC7AC\uC758 \uD589\uBCF5\uC744 \uBBF8\uB8E8\uBA70 \uB178\uB825\uD558\uB294 \uAC83\uC744 '\uD22C\uC790' \uB77C \uBD80\uB974\uACE0, \uC885\uAD50\uB294 \uC8FD\uC74C\uC744 '\uC601\uC0DD'\uC774\uB77C \uBD80\uB978\uB2E4. \uB204\uAD70\uAC00\uC758 \uC704\uB85C\uB294 \uC2E4\uD328\uB97C '\uC9C0\uB098\uACE0 \uBCF4\uBA74 \uB2E4 \uC758\uBBF8 \uC788\uC744 \uC77C'\uC774\uB77C \uBD80\uB978\uB2E4. \uC9D3\uB204\uB974\uB294 \uAC83\uC5D0 \uB2E4\uB978 \uC774\uB984\uC744 \uBD99\uC5EC \uAC70\uB8E9\uD55C \uAC83\uC73C\uB85C \uB9CC\uB4DC\uB294 \uAC83\uC740 \uB2E4 \uBE44\uC57D\uC774\uB2E4."), mdx("p", null, "\uADF8\uB798\uC11C \uCE74\uBB88\uB294 \uC0B6\uC758 \uC9C8\uBCF4\uB2E4 \uC591\uC744 \uB9D0\uD55C\uB2E4. \uAC00\uB2A5\uD55C \uD55C \uB9CE\uC774 \uC758\uC2DD\uD558\uACE0 \uB9CE\uC774 \uACBD\uD5D8\uD558\uB294 \uC77C\uC774 \uC911\uC694\uD574\uC9C4\uB2E4. \uBC30\uC6B0\uC640 \uC815\uBCF5\uC790\uAC00 \uBD80\uC870\uB9AC\uD55C \uC778\uAC04\uC758 \uD615\uC0C1\uC73C\uB85C \uB4F1\uC7A5\uD558\uB294 \uC774\uC720\uB3C4 \uAC19\uB2E4. \uB458 \uB2E4 \uC6B4\uBA85\uC5D0 \uBCF5\uC885\uD558\uC9C0 \uC54A\uACE0 \uC790\uAE30 \uD798\uC73C\uB85C \uD604\uC7AC\uB97C \uBC00\uACE0 \uAC00\uB294 \uC0AC\uB78C\uB4E4\uC774\uB2E4. \uB9E4\uC6B0 \uAD34\uB86D\uAC8C\uB3C4."), mdx("p", null, "\uC774\uC81C \uC2DC\uC9C0\uD504\uB97C \uC0DD\uAC01\uD574\uBCF8\uB2E4. \uCE74\uBB88\uAC00 \uC8FC\uBAA9\uD558\uB294 \uAC83\uC740 \uBC14\uC704\uB97C \uBBF8\uB294 \uC7A5\uBA74\uC774 \uC544\uB2C8\uB77C, \uBC14\uC704\uAC00 \uAD74\uB7EC \uB5A8\uC5B4\uC9C4 \uB4A4 \uB2E4\uC2DC \uC0B0 \uC544\uB798\uB85C \uB0B4\uB824\uC624\uB294 \uADF8 \uC21C\uAC04\uC774\uB2E4. \uADF8 \uC21C\uAC04 \uC2DC\uC9C0\uD504\uB294 \uC790\uAE30 \uB178\uB3D9\uC758 \uD5DB\uB428\uACFC, \uADF8\uAC83\uC774 \uB204\uAD6C\uC758 \uAC83\uC778\uC9C0\uB97C \uC548\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uC2DC\uC9C0\uD504\uC758 \uC18C\uB9AC \uC5C6\uB294 \uAE30\uC068\uC740 \uC1A1\uB450\uB9AC\uC9F8 \uC5EC\uAE30\uC5D0 \uC788\uB2E4. \uADF8\uC758 \uC6B4\uBA85\uC740 \uADF8\uC758 \uAC83\uC774\uB2E4. \uADF8\uC758 \uBC14\uC704\uB294 \uADF8\uC758 \uAC83\uC774\uB2E4.")), mdx("p", null, "\uC0B6\uC758 \uC18C\uC720\uAD8C\uC5D0 \uB300\uD574 \uC0DD\uAC01\uD574\uBCFC \uC218 \uC788\uB2E4. \uC774 \uC18C\uC720\uAD8C\uC740 \uC77C\uBC18\uC801\uC778 \uC790\uC720\uB098 \uD589\uBCF5\uC744 \uB73B\uD558\uC9C0 \uC54A\uB294\uB2E4. \uC790\uAE30 \uC0B6\uC744 \uC790\uAE30 \uAC83\uC73C\uB85C \uB9CC\uB4E0\uB2E4\uACE0 \uD574\uC11C \uC0B6\uC774 \uB354 \uB098\uC544\uC9C0\uC9C0 \uC54A\uB294\uB2E4. \uB354 \uBB34\uAC70\uC6CC\uC9C0\uACE0, \uB354 \uC678\uB85C\uC6CC\uC9C8 \uC218\uB3C4 \uC788\uB2E4. \uC2DC\uC9C0\uD504\uB294 \uADF8 \uB5A0\uC548\uAE30\uB97C \uD55C \uBC88\uB3C4 \uBA48\uCD94\uC9C0 \uC54A\uB294 \uC778\uAC04\uC774\uB2E4. "), mdx("p", null, "\uCE74\uBB88\uAC00 \uB9D0\uD558\uB294 \uC790\uC720\uC758 \uAC1C\uB150\uB3C4 \uBE44\uC2B7\uD558\uB2E4. \uB9D0\uC774 \uC880 \uC6C3\uAE34\uB370 \uC6B0\uB9AC\uAC00 \uC790\uC720\uB77C\uACE0 \uBBFF\uC5B4\uC628 \uAC83\uC774 \uC0AC\uC2E4\uC740 \uB2E4\uB978 \uD615\uD0DC\uC758 \uC18D\uBC15\uC774\uC5C8\uC74C\uC744 \uC778\uC815\uD560 \uC218 \uC788\uB294 \uC790\uC720\uC784\uC744 \uB9D0\uD55C\uB2E4."), mdx("blockquote", null, mdx("p", {
